//go:build frost_native

package signing

import (
	"bytes"
	"context"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"time"

	"github.com/btcsuite/btcd/btcec/v2"
	"github.com/ipfs/go-log/v2"
	"github.com/keep-network/keep-core/pkg/net"
	"github.com/keep-network/keep-core/pkg/protocol/group"
)

const shareRepairMaximumPendingMessages = 1024

// PrepareShareRepairTransportRosterEntry obtains the authorization-scoped
// public key generated by the native signer for one locally owned repair seat.
// Incident tooling collects one entry from each participant over independently
// authenticated operator channels; the offline authority verifies the exact
// authorization/store/seat and workload provenance before signing the
// canonical roster. The returned artifact is not hardware attestation.
func PrepareShareRepairTransportRosterEntry(
	engine NativeTBTCSignerShareRepairEngine,
	authorization *ShareRepairAuthorization,
	authorityPublicKey ed25519.PublicKey,
	participantIdentifier uint16,
) (*ShareRepairTransportPublicKey, error) {
	if engine == nil {
		return nil, fmt.Errorf("share-repair transport preparation engine is nil")
	}
	if _, err := validateShareRepairAuthorization(
		authorization,
		authorityPublicKey,
		false,
	); err != nil {
		return nil, fmt.Errorf("share-repair authorization is invalid: %w", err)
	}
	now := uint64(time.Now().Unix())
	if now < authorization.IssuedAtUnix || now >= authorization.ExpiresAtUnix {
		return nil, fmt.Errorf("share-repair authorization is outside its transport-preparation window")
	}
	participant := group.MemberIndex(participantIdentifier)
	if _, authorized := shareRepairParticipantSet(authorization)[participant]; !authorized {
		return nil, fmt.Errorf("seat [%d] is not in the repair authorization", participantIdentifier)
	}
	session, err := engine.BeginShareRepairSession(
		authorization,
		participantIdentifier,
	)
	if err != nil {
		_ = engine.FinishShareRepairSession(authorization, participantIdentifier)
		return nil, fmt.Errorf("begin native share-repair transport preparation: %w", err)
	}
	finish := func() error {
		return engine.FinishShareRepairSession(authorization, participantIdentifier)
	}
	digest, _ := ComputeShareRepairAuthorizationDigest(authorization)
	if session == nil || session.ContextDigest != fmt.Sprintf("0x%x", digest) ||
		session.ParticipantIdentifier != participantIdentifier ||
		len(session.TransportPublicKey) != shareRepairEphemeralPublicKeyLength {
		_ = finish()
		return nil, fmt.Errorf("native share-repair transport preparation returned an invalid session")
	}
	if _, err := parseCanonicalShareRepairHex32(
		session.StoreFingerprint,
		"native share-repair transport store fingerprint",
	); err != nil {
		_ = finish()
		return nil, err
	}
	publicKey, err := btcec.ParsePubKey(session.TransportPublicKey)
	if err != nil || !bytes.Equal(
		publicKey.SerializeCompressed(),
		session.TransportPublicKey,
	) {
		_ = finish()
		return nil, fmt.Errorf("native share-repair transport preparation returned an invalid public key")
	}
	if err := finish(); err != nil {
		return nil, fmt.Errorf("finish native share-repair transport preparation: %w", err)
	}
	return &ShareRepairTransportPublicKey{
		ParticipantIdentifier: participantIdentifier,
		StoreFingerprint:      session.StoreFingerprint,
		PublicKeyHex:          hex.EncodeToString(session.TransportPublicKey),
	}, nil
}

type shareRepairInstalledWire struct {
	Schema                 string `json:"schema"`
	SessionID              string `json:"session_id"`
	KeyGroup               string `json:"key_group"`
	TargetIdentifier       uint16 `json:"target_identifier"`
	RecoveryEpoch          uint64 `json:"recovery_epoch"`
	AuthorizationDigest    string `json:"authorization_digest"`
	ActiveStoreFingerprint string `json:"active_store_fingerprint"`
	Idempotent             bool   `json:"idempotent"`
}

type shareRepairRunner struct {
	member               group.MemberIndex
	authorization        *ShareRepairAuthorization
	transportRoster      *ShareRepairTransportRoster
	authorizationDigest  [32]byte
	contextWire          string
	participants         map[group.MemberIndex]struct{}
	helperSet            map[group.MemberIndex]struct{}
	engine               NativeTBTCSignerShareRepairEngine
	bus                  shareRepairBus
	stream               <-chan shareRepairMessage
	ephemeralPublic      []byte
	pending              []shareRepairMessage
	pendingBytes         int
	pendingBytesBySender map[group.MemberIndex]int
}

type shareRepairRunnerOutcome struct {
	member group.MemberIndex
	result *NativeShareRepairInstallResult
	err    error
}

// RunShareRepair executes the authenticated confidential RTS protocol for this
// node's local helper/target seats. Every participating node invokes it with
// the same authorization and public package. Only the target node returns a
// non-nil install result; helper-only nodes return nil after delivering sigma.
// The target's native Install call returns only after the existing independent
// state-anchor barrier has acknowledged the durable Rust replacement.
func RunShareRepair(
	ctx context.Context,
	logger log.StandardLogger,
	channel net.BroadcastChannel,
	membershipValidator *group.MembershipValidator,
	engine NativeTBTCSignerShareRepairEngine,
	authorization *ShareRepairAuthorization,
	transportRoster *ShareRepairTransportRoster,
	authorityPublicKey ed25519.PublicKey,
	localMemberIndexes []group.MemberIndex,
) (*NativeShareRepairInstallResult, error) {
	if ctx == nil || engine == nil || len(localMemberIndexes) == 0 {
		return nil, fmt.Errorf("share repair dependencies are incomplete")
	}
	validated, err := validateShareRepairAuthorization(
		authorization,
		authorityPublicKey,
		true,
	)
	if err != nil {
		return nil, fmt.Errorf("share repair authorization is invalid: %w", err)
	}
	if err := ValidateShareRepairTransportRoster(
		transportRoster,
		authorization,
		authorityPublicKey,
	); err != nil {
		return nil, fmt.Errorf("share repair transport roster is invalid: %w", err)
	}
	bus, err := newBroadcastChannelShareRepairBus(
		ctx,
		logger,
		channel,
		membershipValidator,
		shareRepairParticipantSet(authorization),
		validated.digest,
	)
	if err != nil {
		return nil, err
	}
	return runShareRepairOnBus(
		ctx,
		engine,
		authorization,
		transportRoster,
		validated.digest,
		localMemberIndexes,
		bus,
	)
}

func shareRepairParticipantSet(
	authorization *ShareRepairAuthorization,
) map[group.MemberIndex]struct{} {
	participants := make(
		map[group.MemberIndex]struct{},
		len(authorization.HelperIdentifiers)+1,
	)
	for _, helper := range authorization.HelperIdentifiers {
		participants[group.MemberIndex(helper)] = struct{}{}
	}
	participants[group.MemberIndex(authorization.TargetIdentifier)] = struct{}{}
	return participants
}

func shareRepairRosterPublicKeys(
	transportRoster *ShareRepairTransportRoster,
	authorization *ShareRepairAuthorization,
) (map[group.MemberIndex][]byte, error) {
	if _, err := ComputeShareRepairTransportRosterDigest(
		transportRoster,
		authorization,
	); err != nil {
		return nil, err
	}
	publicKeys := make(
		map[group.MemberIndex][]byte,
		len(transportRoster.ParticipantPublicKeys),
	)
	for index, endpoint := range transportRoster.ParticipantPublicKeys {
		publicKey, err := parseCanonicalShareRepairTransportPublicKey(
			endpoint.PublicKeyHex,
			fmt.Sprintf("transport roster public key [%d]", index),
		)
		if err != nil {
			return nil, err
		}
		publicKeys[group.MemberIndex(endpoint.ParticipantIdentifier)] = append(
			[]byte(nil),
			publicKey[:]...,
		)
	}
	return publicKeys, nil
}

func runShareRepairOnBus(
	ctx context.Context,
	engine NativeTBTCSignerShareRepairEngine,
	authorization *ShareRepairAuthorization,
	transportRoster *ShareRepairTransportRoster,
	authorizationDigest [32]byte,
	localMemberIndexes []group.MemberIndex,
	bus shareRepairBus,
) (targetResult *NativeShareRepairInstallResult, resultErr error) {
	if ctx == nil || engine == nil || authorization == nil || transportRoster == nil ||
		bus == nil || len(localMemberIndexes) == 0 {
		return nil, fmt.Errorf("share repair runner dependencies are incomplete")
	}
	participants := shareRepairParticipantSet(authorization)
	rosterPublicKeys, err := shareRepairRosterPublicKeys(
		transportRoster,
		authorization,
	)
	if err != nil {
		return nil, fmt.Errorf("invalid share-repair transport roster: %w", err)
	}
	helperSet := make(map[group.MemberIndex]struct{}, len(authorization.HelperIdentifiers))
	for _, helper := range authorization.HelperIdentifiers {
		member := group.MemberIndex(helper)
		helperSet[member] = struct{}{}
	}

	localSet := make(map[group.MemberIndex]struct{}, len(localMemberIndexes))
	runners := make([]*shareRepairRunner, 0, len(localMemberIndexes))
	defer func() {
		for index := len(runners) - 1; index >= 0; index-- {
			runner := runners[index]
			if err := engine.FinishShareRepairSession(
				authorization,
				uint16(runner.member),
			); err != nil && resultErr == nil {
				resultErr = fmt.Errorf(
					"finish native share-repair session for seat [%d]: %w",
					runner.member,
					err,
				)
			}
		}
	}()
	for _, member := range localMemberIndexes {
		if _, duplicate := localSet[member]; duplicate {
			return nil, fmt.Errorf("duplicate local share-repair seat [%d]", member)
		}
		localSet[member] = struct{}{}
		if _, participating := participants[member]; !participating {
			return nil, fmt.Errorf("local seat [%d] is not in the repair authorization", member)
		}
		session, err := engine.BeginShareRepairSession(
			authorization,
			uint16(member),
		)
		if err != nil {
			// Begin may have created native state before a bridge-side decode or
			// post-call validation failed. Finish is idempotent, including when
			// Begin failed before creating a session.
			_ = engine.FinishShareRepairSession(authorization, uint16(member))
			return nil, fmt.Errorf("begin native share-repair session for seat [%d]: %w", member, err)
		}
		if session == nil || session.ContextDigest != fmt.Sprintf("0x%x", authorizationDigest) ||
			session.ParticipantIdentifier != uint16(member) ||
			len(session.TransportPublicKey) != shareRepairEphemeralPublicKeyLength {
			_ = engine.FinishShareRepairSession(authorization, uint16(member))
			return nil, fmt.Errorf("native share-repair session for seat [%d] is invalid", member)
		}
		rosterEndpoint, found := shareRepairRosterEndpoint(
			transportRoster,
			member,
		)
		if !found || session.StoreFingerprint != rosterEndpoint.StoreFingerprint {
			_ = engine.FinishShareRepairSession(authorization, uint16(member))
			return nil, fmt.Errorf(
				"native share-repair session for seat [%d] does not match the signed store binding",
				member,
			)
		}
		if _, err := btcec.ParsePubKey(session.TransportPublicKey); err != nil {
			_ = engine.FinishShareRepairSession(authorization, uint16(member))
			return nil, fmt.Errorf("native share-repair session for seat [%d] returned an invalid public key: %w", member, err)
		}
		if !bytes.Equal(session.TransportPublicKey, rosterPublicKeys[member]) {
			_ = engine.FinishShareRepairSession(authorization, uint16(member))
			return nil, fmt.Errorf(
				"native share-repair session for seat [%d] does not match the signed transport roster",
				member,
			)
		}
		runners = append(runners, &shareRepairRunner{
			member:              member,
			authorization:       authorization,
			transportRoster:     transportRoster,
			authorizationDigest: authorizationDigest,
			contextWire:         fmt.Sprintf("0x%x", authorizationDigest),
			participants:        participants,
			helperSet:           helperSet,
			engine:              engine,
			bus:                 bus,
			stream:              bus.Subscribe(member),
			ephemeralPublic:     append([]byte(nil), session.TransportPublicKey...),
		})
	}
	bus.Start()
	runContext, cancel := context.WithCancel(ctx)
	defer cancel()

	outcomes := make(chan shareRepairRunnerOutcome, len(runners))
	for _, runner := range runners {
		runner := runner
		go func() {
			result, err := runner.run(runContext)
			outcomes <- shareRepairRunnerOutcome{member: runner.member, result: result, err: err}
		}()
	}

	var firstError error
	for range runners {
		outcome := <-outcomes
		if outcome.err != nil && firstError == nil {
			firstError = fmt.Errorf("share repair seat [%d] failed: %w", outcome.member, outcome.err)
			cancel()
		}
		if outcome.result != nil {
			if targetResult != nil {
				firstError = fmt.Errorf("multiple local target results were returned")
			} else {
				targetResult = outcome.result
			}
		}
	}
	if firstError != nil {
		return targetResult, firstError
	}
	if _, targetLocal := localSet[group.MemberIndex(authorization.TargetIdentifier)]; targetLocal &&
		targetResult == nil {
		return nil, fmt.Errorf("local share-repair target returned no install result")
	}
	return targetResult, nil
}

func (runner *shareRepairRunner) run(
	ctx context.Context,
) (*NativeShareRepairInstallResult, error) {
	announcement := shareRepairMessage{
		Type:               shareRepairAnnouncementMessage,
		Sender:             runner.member,
		ContextDigest:      runner.authorizationDigest,
		EphemeralPublicKey: runner.ephemeralPublic,
	}
	// BroadcastChannel.Send owns context-lifetime retransmission. Publishing
	// this announcement again at the application layer would register another
	// independent retransmission handler on every repeat and turn a missing-peer
	// timeout into quadratic traffic growth.
	cancelAnnouncement := runner.bus.Broadcast(announcement)
	defer cancelAnnouncement()

	_, err := runner.collectAnnouncements(ctx)
	if err != nil {
		return nil, err
	}
	if runner.member == group.MemberIndex(runner.authorization.TargetIdentifier) {
		return runner.runTarget(ctx)
	}
	if _, helper := runner.helperSet[runner.member]; !helper {
		return nil, fmt.Errorf("seat is neither target nor helper")
	}
	return nil, runner.runHelper(ctx, cancelAnnouncement)
}

func (runner *shareRepairRunner) collectAnnouncements(
	ctx context.Context,
) (map[group.MemberIndex][]byte, error) {
	publicKeys := make(map[group.MemberIndex][]byte, len(runner.participants))
	selfPublic, err := btcec.ParsePubKey(runner.ephemeralPublic)
	if err != nil {
		return nil, fmt.Errorf("cannot parse local recovery ephemeral key: %w", err)
	}
	publicKeys[runner.member] = selfPublic.SerializeCompressed()
	for len(publicKeys) < len(runner.participants) {
		var message shareRepairMessage
		select {
		case <-ctx.Done():
			return nil, fmt.Errorf("collect recovery announcements: %w", ctx.Err())
		case message = <-runner.stream:
		}
		if message.ContextDigest != runner.authorizationDigest {
			continue
		}
		// The transport enforces this exact authorization set for network
		// traffic. Keep the same guard here for in-process and test buses so a
		// nonparticipant cannot fill the bounded early-message queue.
		if _, expected := runner.participants[message.Sender]; !expected {
			continue
		}
		if message.Type != shareRepairAnnouncementMessage {
			if err := runner.bufferPendingMessage(message); err != nil {
				return nil, err
			}
			continue
		}
		parsed, err := btcec.ParsePubKey(message.EphemeralPublicKey)
		if err != nil {
			return nil, fmt.Errorf("invalid recovery announcement from [%d]: %w", message.Sender, err)
		}
		parsedWire := parsed.SerializeCompressed()
		expectedPublicKey, expected := shareRepairRosterPublicKey(
			runner.transportRoster,
			message.Sender,
		)
		if !expected || !bytes.Equal(expectedPublicKey, parsedWire) {
			return nil, fmt.Errorf(
				"recovery seat [%d] announced a key outside the signed transport roster",
				message.Sender,
			)
		}
		if existing, seen := publicKeys[message.Sender]; seen {
			if !bytes.Equal(existing, parsedWire) {
				return nil, fmt.Errorf("recovery seat [%d] equivocated its ephemeral key", message.Sender)
			}
			continue
		}
		publicKeys[message.Sender] = parsedWire
	}
	return publicKeys, nil
}

func (runner *shareRepairRunner) bufferPendingMessage(
	message shareRepairMessage,
) error {
	if len(runner.pending) >= shareRepairMaximumPendingMessages {
		return fmt.Errorf(
			"share-repair pending-message limit exceeded before announcements completed",
		)
	}
	messageBytes := shareRepairMessageRetainedBytes(message)
	if messageBytes > shareRepairMaximumSessionBytesPerSender-
		runner.pendingBytesBySender[message.Sender] {
		return fmt.Errorf(
			"share-repair pending-byte limit exceeded for sender [%d] before announcements completed",
			message.Sender,
		)
	}
	if messageBytes > shareRepairMaximumSessionBytes-runner.pendingBytes {
		return fmt.Errorf(
			"share-repair total pending-byte limit exceeded before announcements completed",
		)
	}
	if runner.pendingBytesBySender == nil {
		runner.pendingBytesBySender = make(map[group.MemberIndex]int)
	}
	runner.pending = append(runner.pending, message)
	runner.pendingBytes += messageBytes
	runner.pendingBytesBySender[message.Sender] += messageBytes
	return nil
}

func shareRepairRosterPublicKey(
	transportRoster *ShareRepairTransportRoster,
	member group.MemberIndex,
) ([]byte, bool) {
	if transportRoster == nil {
		return nil, false
	}
	for _, endpoint := range transportRoster.ParticipantPublicKeys {
		if endpoint.ParticipantIdentifier != uint16(member) {
			continue
		}
		publicKey, err := parseCanonicalShareRepairTransportPublicKey(
			endpoint.PublicKeyHex,
			"transport roster public key",
		)
		if err != nil {
			return nil, false
		}
		return append([]byte(nil), publicKey[:]...), true
	}
	return nil, false
}

func shareRepairRosterEndpoint(
	transportRoster *ShareRepairTransportRoster,
	member group.MemberIndex,
) (*ShareRepairTransportPublicKey, bool) {
	if transportRoster == nil {
		return nil, false
	}
	for index := range transportRoster.ParticipantPublicKeys {
		if transportRoster.ParticipantPublicKeys[index].ParticipantIdentifier == uint16(member) {
			return &transportRoster.ParticipantPublicKeys[index], true
		}
	}
	return nil, false
}

func (runner *shareRepairRunner) nextMessage(
	ctx context.Context,
) (shareRepairMessage, error) {
	if len(runner.pending) > 0 {
		message := runner.pending[0]
		messageBytes := shareRepairMessageRetainedBytes(message)
		if messageBytes >= runner.pendingBytesBySender[message.Sender] {
			delete(runner.pendingBytesBySender, message.Sender)
		} else {
			runner.pendingBytesBySender[message.Sender] -= messageBytes
		}
		if messageBytes >= runner.pendingBytes {
			runner.pendingBytes = 0
		} else {
			runner.pendingBytes -= messageBytes
		}
		runner.pending[0] = shareRepairMessage{}
		runner.pending = runner.pending[1:]
		if len(runner.pending) == 0 {
			// Drop the backing array as soon as rendezvous traffic has drained so
			// no payload references or stale accounting survive into later phases.
			runner.pending = nil
			runner.pendingBytes = 0
			runner.pendingBytesBySender = nil
		}
		return message, nil
	}
	select {
	case <-ctx.Done():
		return shareRepairMessage{}, ctx.Err()
	case message := <-runner.stream:
		return message, nil
	}
}

func retainFirstShareRepairDelta(
	deltas map[uint16]*NativeShareRepairEncryptedDelta,
	message shareRepairMessage,
	contextWire string,
	recipientIdentifier uint16,
) {
	senderIdentifier := uint16(message.Sender)
	if deltas[senderIdentifier] != nil {
		return
	}
	deltas[senderIdentifier] = &NativeShareRepairEncryptedDelta{
		ContextDigest:       contextWire,
		SenderIdentifier:    senderIdentifier,
		RecipientIdentifier: recipientIdentifier,
		Payload:             append([]byte(nil), message.Payload...),
	}
}

func retainFirstShareRepairSigma(
	sigmas map[uint16]*NativeShareRepairEncryptedSigma,
	message shareRepairMessage,
	contextWire string,
) {
	helperIdentifier := uint16(message.Sender)
	if sigmas[helperIdentifier] != nil {
		return
	}
	sigmas[helperIdentifier] = &NativeShareRepairEncryptedSigma{
		ContextDigest:    contextWire,
		HelperIdentifier: helperIdentifier,
		Payload:          append([]byte(nil), message.Payload...),
	}
}

func (runner *shareRepairRunner) runHelper(
	ctx context.Context,
	cancelAnnouncement context.CancelFunc,
) error {
	part1, err := runner.engine.ShareRepairPart1(
		runner.authorization,
		uint16(runner.member),
		runner.transportRoster,
	)
	if err != nil {
		return fmt.Errorf("native repair part1: %w", err)
	}
	if part1 == nil || part1.ContextDigest != runner.contextWire ||
		part1.HelperIdentifier != uint16(runner.member) ||
		part1.PublicKeyPackage == nil ||
		len(part1.PublicKeyPackage.VerifyingShares) != int(runner.authorization.ParticipantCount) ||
		part1.PublicKeyPackage.VerifyingKey == "" ||
		len(part1.Deltas) != len(runner.authorization.HelperIdentifiers) {
		return fmt.Errorf("native repair part1 returned the wrong context or delta set")
	}
	publicPackage, err := json.Marshal(part1.PublicKeyPackage)
	if err != nil {
		return fmt.Errorf("encode repair public key package: %w", err)
	}
	if len(publicPackage) > shareRepairMaximumPublicPayload {
		return fmt.Errorf("repair public key package exceeds the transport cap")
	}
	// A participant cannot cancel its announcement merely because it has heard
	// every peer: another peer may still be missing this participant. The
	// installed receipt proves all helpers crossed rendezvous, so retain the
	// announcement with the helper's other pre-receipt messages until then.
	preReceiptBroadcasts := make(
		[]context.CancelFunc,
		0,
		len(runner.helperSet)+3,
	)
	preReceiptBroadcasts = append(preReceiptBroadcasts, cancelAnnouncement)
	cancelPreReceiptBroadcasts := func() {
		for _, cancel := range preReceiptBroadcasts {
			cancel()
		}
		preReceiptBroadcasts = nil
	}
	defer cancelPreReceiptBroadcasts()
	preReceiptBroadcasts = append(preReceiptBroadcasts, runner.bus.Broadcast(shareRepairMessage{
		Type:          shareRepairPublicPackageMessage,
		Sender:        runner.member,
		ContextDigest: runner.authorizationDigest,
		Payload:       publicPackage,
	}))
	for index, recipient := range runner.authorization.HelperIdentifiers {
		delta := part1.Deltas[index]
		if delta == nil || delta.ContextDigest != runner.contextWire ||
			delta.SenderIdentifier != uint16(runner.member) ||
			delta.RecipientIdentifier != recipient ||
			len(delta.Payload) != shareRepairEncryptedScalarPayloadLength {
			return fmt.Errorf("native repair part1 delta [%d] is invalid", index)
		}
		preReceiptBroadcasts = append(preReceiptBroadcasts, runner.bus.Broadcast(shareRepairMessage{
			Type:          shareRepairDeltaMessage,
			Sender:        runner.member,
			Recipient:     group.MemberIndex(recipient),
			ContextDigest: runner.authorizationDigest,
			Payload:       append([]byte(nil), delta.Payload...),
		}))
	}

	deltas := make(map[uint16]*NativeShareRepairEncryptedDelta, len(runner.helperSet))
	for len(deltas) < len(runner.helperSet) {
		message, err := runner.nextMessage(ctx)
		if err != nil {
			return fmt.Errorf("collect recovery deltas: %w", err)
		}
		if message.Type != shareRepairDeltaMessage ||
			message.ContextDigest != runner.authorizationDigest ||
			message.Recipient != runner.member ||
			len(message.Payload) != shareRepairEncryptedScalarPayloadLength {
			continue
		}
		if _, expected := runner.helperSet[message.Sender]; !expected {
			continue
		}
		senderIdentifier := uint16(message.Sender)
		if deltas[senderIdentifier] != nil {
			// Native Part1 rows are deterministic for the exact signed bundle, but
			// every ECIES envelope is freshly randomized. Retain one bounded
			// candidate; byte inequality is not semantic equivocation.
			continue
		}
		retainFirstShareRepairDelta(
			deltas,
			message,
			runner.contextWire,
			uint16(runner.member),
		)
	}
	ordered := make([]*NativeShareRepairEncryptedDelta, 0, len(deltas))
	for _, sender := range runner.authorization.HelperIdentifiers {
		ordered = append(ordered, deltas[sender])
	}
	part2, err := runner.engine.ShareRepairPart2(
		runner.authorization,
		uint16(runner.member),
		ordered,
		runner.transportRoster,
	)
	if err != nil {
		return fmt.Errorf("native repair part2: %w", err)
	}
	if part2 == nil || part2.ContextDigest != runner.contextWire || part2.Sigma == nil ||
		part2.Sigma.ContextDigest != runner.contextWire ||
		part2.Sigma.HelperIdentifier != uint16(runner.member) ||
		len(part2.Sigma.Payload) != shareRepairEncryptedScalarPayloadLength {
		return fmt.Errorf("native repair part2 returned an invalid sigma")
	}
	preReceiptBroadcasts = append(preReceiptBroadcasts, runner.bus.Broadcast(shareRepairMessage{
		Type:          shareRepairSigmaMessage,
		Sender:        runner.member,
		Recipient:     group.MemberIndex(runner.authorization.TargetIdentifier),
		ContextDigest: runner.authorizationDigest,
		Payload:       append([]byte(nil), part2.Sigma.Payload...),
	}))
	return runner.waitForInstalledReceipt(ctx, cancelPreReceiptBroadcasts)
}

func (runner *shareRepairRunner) runTarget(
	ctx context.Context,
) (*NativeShareRepairInstallResult, error) {
	sigmas := make(map[uint16]*NativeShareRepairEncryptedSigma, len(runner.helperSet))
	publicPackages := make(map[uint16][]byte, len(runner.helperSet))
	var publicKeyPackage *NativeFROSTPublicKeyPackage
	var canonicalPublicKeyPackage []byte
	for len(sigmas) < len(runner.helperSet) || len(publicPackages) < len(runner.helperSet) {
		message, err := runner.nextMessage(ctx)
		if err != nil {
			return nil, fmt.Errorf("collect recovery sigmas: %w", err)
		}
		if message.ContextDigest != runner.authorizationDigest {
			continue
		}
		if _, expected := runner.helperSet[message.Sender]; !expected {
			continue
		}
		if message.Type == shareRepairPublicPackageMessage {
			candidate := &NativeFROSTPublicKeyPackage{}
			decoder := json.NewDecoder(bytes.NewReader(message.Payload))
			decoder.DisallowUnknownFields()
			if err := decoder.Decode(candidate); err != nil {
				return nil, fmt.Errorf("decode repair public package from [%d]: %w", message.Sender, err)
			}
			if err := decoder.Decode(&struct{}{}); err != io.EOF {
				return nil, fmt.Errorf("repair public package from [%d] has trailing JSON", message.Sender)
			}
			if len(candidate.VerifyingShares) != int(runner.authorization.ParticipantCount) ||
				candidate.VerifyingKey == "" {
				return nil, fmt.Errorf("repair public package from [%d] has the wrong shape", message.Sender)
			}
			canonical, err := json.Marshal(candidate)
			if err != nil {
				return nil, fmt.Errorf("canonicalize repair public package: %w", err)
			}
			if existing := publicPackages[uint16(message.Sender)]; existing != nil {
				if !bytes.Equal(existing, canonical) {
					return nil, fmt.Errorf("repair helper [%d] equivocated its public package", message.Sender)
				}
				continue
			}
			if canonicalPublicKeyPackage != nil &&
				!bytes.Equal(canonicalPublicKeyPackage, canonical) {
				return nil, fmt.Errorf("repair helpers disagree on the public key package")
			}
			canonicalPublicKeyPackage = append([]byte(nil), canonical...)
			publicPackages[uint16(message.Sender)] = canonical
			publicKeyPackage = candidate
			continue
		}
		if message.Type != shareRepairSigmaMessage || message.Recipient != runner.member ||
			len(message.Payload) != shareRepairEncryptedScalarPayloadLength {
			continue
		}
		helperIdentifier := uint16(message.Sender)
		if sigmas[helperIdentifier] != nil {
			// Retries may carry a fresh ECIES encoding of the same deterministic
			// bundle slot. Keep the first candidate and bound memory to one sigma
			// per authorized helper.
			continue
		}
		retainFirstShareRepairSigma(sigmas, message, runner.contextWire)
	}
	ordered := make([]*NativeShareRepairEncryptedSigma, 0, len(sigmas))
	for _, helper := range runner.authorization.HelperIdentifiers {
		ordered = append(ordered, sigmas[helper])
	}
	result, err := runner.engine.InstallRepairedShare(
		runner.authorization,
		publicKeyPackage,
		ordered,
		runner.transportRoster,
	)
	if err != nil {
		return nil, fmt.Errorf("native repaired-share install: %w", err)
	}
	if result == nil || result.Schema != ShareRepairInstallResultSchema ||
		result.SessionID != runner.authorization.SessionID ||
		result.KeyGroup != runner.authorization.KeyGroup ||
		result.TargetIdentifier != runner.authorization.TargetIdentifier ||
		result.RecoveryEpoch != runner.authorization.RecoveryEpoch ||
		result.AuthorizationDigest != runner.contextWire ||
		result.ActiveStoreFingerprint != runner.authorization.NewStoreFingerprint {
		return nil, fmt.Errorf("native repaired-share install result does not match authorization")
	}
	if err := recordInstalledShareRepair(result); err != nil {
		return nil, fmt.Errorf("arm repaired-seat activation guard: %w", err)
	}
	if err := runner.publishInstalledReceiptAndWaitForAcknowledgements(
		ctx,
		result,
	); err != nil {
		return result, fmt.Errorf(
			"repaired share was durably installed and anchor-acknowledged, but receipt acknowledgements are incomplete: %w",
			err,
		)
	}
	return result, nil
}

func (runner *shareRepairRunner) publishInstalledReceiptAndWaitForAcknowledgements(
	ctx context.Context,
	result *NativeShareRepairInstallResult,
) error {
	receipt, err := json.Marshal(shareRepairInstalledWire{
		Schema:                 result.Schema,
		SessionID:              result.SessionID,
		KeyGroup:               result.KeyGroup,
		TargetIdentifier:       result.TargetIdentifier,
		RecoveryEpoch:          result.RecoveryEpoch,
		AuthorizationDigest:    result.AuthorizationDigest,
		ActiveStoreFingerprint: result.ActiveStoreFingerprint,
		Idempotent:             result.Idempotent,
	})
	if err != nil {
		return fmt.Errorf("encode repaired-share installed receipt: %w", err)
	}
	receiptDigest := sha256.Sum256(receipt)
	// Publish once. The network layer keeps this exact sequence number alive
	// while the target waits below, until every authorized helper proves it saw
	// the durable, anchor-acknowledged result or the maintenance deadline fires.
	cancelReceipt := runner.bus.Broadcast(shareRepairMessage{
		Type:          shareRepairInstalledMessage,
		Sender:        runner.member,
		ContextDigest: runner.authorizationDigest,
		Payload:       receipt,
	})
	defer cancelReceipt()
	if err := runner.waitForInstalledAcknowledgements(ctx, receiptDigest); err != nil {
		return fmt.Errorf("confirm repaired-share installed receipt: %w", err)
	}
	cancelReceipt()
	// This final signal is only an early-release optimization for helpers. A
	// helper already knows the install is durable from the validated receipt;
	// if this signal is lost, it safely keeps its one acknowledgement
	// retransmitter alive until the maintenance deadline instead of adding
	// application-level repeats.
	cancelCompletion := runner.bus.Broadcast(shareRepairMessage{
		Type:          shareRepairCompletionMessage,
		Sender:        runner.member,
		ContextDigest: runner.authorizationDigest,
		Payload:       append([]byte(nil), receiptDigest[:]...),
	})
	cancelCompletion()
	return nil
}

func (runner *shareRepairRunner) waitForInstalledAcknowledgements(
	ctx context.Context,
	receiptDigest [sha256.Size]byte,
) error {
	acknowledged := make(map[group.MemberIndex]struct{}, len(runner.helperSet))
	for len(acknowledged) < len(runner.helperSet) {
		message, err := runner.nextMessage(ctx)
		if err != nil {
			return fmt.Errorf("wait for repaired-share receipt acknowledgements: %w", err)
		}
		if message.Type != shareRepairInstalledAcknowledgementMessage ||
			message.ContextDigest != runner.authorizationDigest ||
			message.Recipient != runner.member {
			continue
		}
		if _, expected := runner.helperSet[message.Sender]; !expected {
			continue
		}
		if len(message.Payload) != sha256.Size ||
			!bytes.Equal(message.Payload, receiptDigest[:]) {
			return fmt.Errorf(
				"helper [%d] acknowledged a different installed receipt",
				message.Sender,
			)
		}
		acknowledged[message.Sender] = struct{}{}
	}
	return nil
}

func (runner *shareRepairRunner) waitForInstalledReceipt(
	ctx context.Context,
	cancelPreReceiptBroadcasts context.CancelFunc,
) error {
	for {
		message, err := runner.nextMessage(ctx)
		if err != nil {
			return fmt.Errorf("wait for repaired-share installed receipt: %w", err)
		}
		if message.Type != shareRepairInstalledMessage ||
			message.ContextDigest != runner.authorizationDigest ||
			message.Sender != group.MemberIndex(runner.authorization.TargetIdentifier) {
			continue
		}
		receipt := &shareRepairInstalledWire{}
		decoder := json.NewDecoder(bytes.NewReader(message.Payload))
		decoder.DisallowUnknownFields()
		if err := decoder.Decode(receipt); err != nil {
			return fmt.Errorf("decode repaired-share installed receipt: %w", err)
		}
		if err := decoder.Decode(&struct{}{}); err != io.EOF {
			return fmt.Errorf("repaired-share installed receipt has trailing JSON")
		}
		if receipt.Schema != ShareRepairInstallResultSchema ||
			receipt.SessionID != runner.authorization.SessionID ||
			receipt.KeyGroup != runner.authorization.KeyGroup ||
			receipt.TargetIdentifier != runner.authorization.TargetIdentifier ||
			receipt.RecoveryEpoch != runner.authorization.RecoveryEpoch ||
			receipt.AuthorizationDigest != runner.contextWire ||
			receipt.ActiveStoreFingerprint != runner.authorization.NewStoreFingerprint {
			return fmt.Errorf("repaired-share installed receipt does not match authorization")
		}
		receiptDigest := sha256.Sum256(message.Payload)
		cancelPreReceiptBroadcasts()
		cancelAcknowledgement := runner.bus.Broadcast(shareRepairMessage{
			Type:          shareRepairInstalledAcknowledgementMessage,
			Sender:        runner.member,
			Recipient:     group.MemberIndex(runner.authorization.TargetIdentifier),
			ContextDigest: runner.authorizationDigest,
			Payload:       append([]byte(nil), receiptDigest[:]...),
		})
		defer cancelAcknowledgement()
		return runner.waitForShareRepairCompletion(ctx, receiptDigest)
	}
}

func (runner *shareRepairRunner) waitForShareRepairCompletion(
	ctx context.Context,
	receiptDigest [sha256.Size]byte,
) error {
	for {
		message, err := runner.nextMessage(ctx)
		if err != nil {
			// Receipt validation already proved the target durably installed and
			// anchor-acknowledged the share. Waiting keeps this helper's single ACK
			// retransmitter alive; exhausting the enclosing maintenance window does
			// not invalidate that completed repair.
			if ctx.Err() == context.DeadlineExceeded {
				return nil
			}
			return fmt.Errorf("wait for share-repair completion: %w", err)
		}
		if message.Type != shareRepairCompletionMessage ||
			message.ContextDigest != runner.authorizationDigest ||
			message.Sender != group.MemberIndex(runner.authorization.TargetIdentifier) ||
			message.Recipient != 0 {
			continue
		}
		if len(message.Payload) != sha256.Size ||
			!bytes.Equal(message.Payload, receiptDigest[:]) {
			return fmt.Errorf("target completed a different installed receipt")
		}
		return nil
	}
}
